// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_CP: NistCatalogFamily = {"code":"CP","name":"Contingency Planning","controls":[{"id":"CP-1","oscal_id":"cp-1","family":"CP","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> contingency planning policy that:\n    <organization-defined parameter> contingency planning policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the contingency planning policy and the associated contingency planning controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the contingency planning policy and procedures; and\nc. Review and update the current contingency planning:\n  Review and update the current contingency planning:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Contingency planning policy and procedures address the controls in the CP family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on the development of contingency planning policy and procedures. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission- or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies that reflect the complex nature of organizations. Procedures can be established for security and privacy programs, for mission or business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to contingency planning policy and procedures include assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"cp-1_prm_1","label":"organization-defined personnel or roles"},{"id":"cp-01_odp.01","label":"personnel or roles"},{"id":"cp-01_odp.02","label":"personnel or roles"},{"id":"cp-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"cp-01_odp.04","label":"official"},{"id":"cp-01_odp.05","label":"frequency"},{"id":"cp-01_odp.06","label":"events"},{"id":"cp-01_odp.07","label":"frequency"},{"id":"cp-01_odp.08","label":"events"}],"objectives":[{"id":"cp-1_obj.a-1","label":"CP-01a.[01]","text":"a contingency planning policy is developed and documented;"},{"id":"cp-1_obj.a-2","label":"CP-01a.[02]","text":"the contingency planning policy is disseminated to {{ insert: param, cp-01_odp.01 }};"},{"id":"cp-1_obj.a-3","label":"CP-01a.[03]","text":"contingency planning procedures to facilitate the implementation of the contingency planning policy and associated contingency planning controls are developed and documented;"},{"id":"cp-1_obj.a-4","label":"CP-01a.[04]","text":"the contingency planning procedures are disseminated to {{ insert: param, cp-01_odp.02 }};"},{"id":"cp-1_obj.a.1.a-1","label":"CP-01a.01(a)[01]","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy addresses purpose;"},{"id":"cp-1_obj.a.1.a-2","label":"CP-01a.01(a)[02]","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy addresses scope;"},{"id":"cp-1_obj.a.1.a-3","label":"CP-01a.01(a)[03]","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy addresses roles;"},{"id":"cp-1_obj.a.1.a-4","label":"CP-01a.01(a)[04]","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy addresses responsibilities;"},{"id":"cp-1_obj.a.1.a-5","label":"CP-01a.01(a)[05]","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy addresses management commitment;"},{"id":"cp-1_obj.a.1.a-6","label":"CP-01a.01(a)[06]","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy addresses coordination among organizational entities;"},{"id":"cp-1_obj.a.1.a-7","label":"CP-01a.01(a)[07]","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy addresses compliance;"},{"id":"cp-1_obj.a.1.b","label":"CP-01a.01(b)","text":"the {{ insert: param, cp-01_odp.03 }} contingency planning policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"cp-1_obj.b","label":"CP-01b.","text":"the {{ insert: param, cp-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the contingency planning policy and procedures;"},{"id":"cp-1_obj.c.1-1","label":"CP-01c.01[01]","text":"the current contingency planning policy is reviewed and updated {{ insert: param, cp-01_odp.05 }};"},{"id":"cp-1_obj.c.1-2","label":"CP-01c.01[02]","text":"the current contingency planning policy is reviewed and updated following {{ insert: param, cp-01_odp.06 }};"},{"id":"cp-1_obj.c.2-1","label":"CP-01c.02[01]","text":"the current contingency planning procedures are reviewed and updated {{ insert: param, cp-01_odp.07 }};"},{"id":"cp-1_obj.c.2-2","label":"CP-01c.02[02]","text":"the current contingency planning procedures are reviewed and updated following {{ insert: param, cp-01_odp.08 }}."}],"methods":[{"method":"examine","label":"CP-01-Examine"},{"method":"interview","label":"CP-01-Interview"}],"references":[{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-34"},{"title":"SP 800-39"},{"title":"SP 800-50"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SI-12"]},{"id":"CP-2","oscal_id":"cp-2","family":"CP","title":"Contingency Plan","statement":"a. Develop a contingency plan for the system that:\n  Develop a contingency plan for the system that:\n  1. Identifies essential mission and business functions and associated contingency requirements;\n  2. Provides recovery objectives, restoration priorities, and metrics;\n  3. Addresses contingency roles, responsibilities, assigned individuals with contact information;\n  4. Addresses maintaining essential mission and business functions despite a system disruption, compromise, or failure;\n  5. Addresses eventual, full system restoration without deterioration of the controls originally planned and implemented;\n  6. Addresses the sharing of contingency information; and\n  7. Is reviewed and approved by <organization-defined personnel or roles>;\nb. Distribute copies of the contingency plan to <organization-defined key contingency personnel (identified by name and/or by role) and organizational elements>;\nc. Coordinate contingency planning activities with incident handling activities;\nd. Review the contingency plan for the system <frequency>;\ne. Update the contingency plan to address changes to the organization, system, or environment of operation and problems encountered during contingency plan implementation, execution, or testing;\nf. Communicate contingency plan changes to <organization-defined key contingency personnel (identified by name and/or by role) and organizational elements>;\ng. Incorporate lessons learned from contingency plan testing, training, or actual contingency activities into contingency testing and training; and\nh. Protect the contingency plan from unauthorized disclosure and modification.","supplemental_guidance":"Contingency planning for systems is part of an overall program for achieving continuity of operations for organizational mission and business functions. Contingency planning addresses system restoration and implementation of alternative mission or business processes when systems are compromised or breached. Contingency planning is considered throughout the system development life cycle and is a fundamental part of the system design. Systems can be designed for redundancy, to provide backup capabilities, and for resilience. Contingency plans reflect the degree of restoration required for organizational systems since not all systems need to fully recover to achieve the level of continuity of operations desired. System recovery objectives reflect applicable laws, executive orders, directives, regulations, policies, standards, guidelines, organizational risk tolerance, and system impact level.\n\nActions addressed in contingency plans include orderly system degradation, system shutdown, fallback to a manual mode, alternate information flows, and operating in modes reserved for when systems are under attack. By coordinating contingency planning with incident handling activities, organizations ensure that the necessary planning activities are in place and activated in the event of an incident. Organizations consider whether continuity of operations during an incident conflicts with the capability to automatically disable the system, as specified in [IR-4(5)](#ir-4.5) . Incident response planning is part of contingency planning for organizations and is addressed in the [IR](#ir) (Incident Response) family.","implementation_level":"organization","parameters":[{"id":"cp-2_prm_1","label":"organization-defined personnel or roles"},{"id":"cp-2_prm_2","label":"organization-defined key contingency personnel (identified by name and/or by role) and organizational elements"},{"id":"cp-2_prm_4","label":"organization-defined key contingency personnel (identified by name and/or by role) and organizational elements"},{"id":"cp-02_odp.01","label":"personnel or roles"},{"id":"cp-02_odp.02","label":"personnel or roles"},{"id":"cp-02_odp.03","label":"key contingency personnel"},{"id":"cp-02_odp.04","label":"organizational elements"},{"id":"cp-02_odp.05","label":"frequency"},{"id":"cp-02_odp.06","label":"key contingency personnel"},{"id":"cp-02_odp.07","label":"organizational elements"}],"objectives":[{"id":"cp-2_obj.a.1","label":"CP-02a.01","text":"a contingency plan for the system is developed that identifies essential mission and business functions and associated contingency requirements;"},{"id":"cp-2_obj.a.2-1","label":"CP-02a.02[01]","text":"a contingency plan for the system is developed that provides recovery objectives;"},{"id":"cp-2_obj.a.2-2","label":"CP-02a.02[02]","text":"a contingency plan for the system is developed that provides restoration priorities;"},{"id":"cp-2_obj.a.2-3","label":"CP-02a.02[03]","text":"a contingency plan for the system is developed that provides metrics;"},{"id":"cp-2_obj.a.3-1","label":"CP-02a.03[01]","text":"a contingency plan for the system is developed that addresses contingency roles;"},{"id":"cp-2_obj.a.3-2","label":"CP-02a.03[02]","text":"a contingency plan for the system is developed that addresses contingency responsibilities;"},{"id":"cp-2_obj.a.3-3","label":"CP-02a.03[03]","text":"a contingency plan for the system is developed that addresses assigned individuals with contact information;"},{"id":"cp-2_obj.a.4","label":"CP-02a.04","text":"a contingency plan for the system is developed that addresses maintaining essential mission and business functions despite a system disruption, compromise, or failure;"},{"id":"cp-2_obj.a.5","label":"CP-02a.05","text":"a contingency plan for the system is developed that addresses eventual, full-system restoration without deterioration of the controls originally planned and implemented;"},{"id":"cp-2_obj.a.6","label":"CP-02a.06","text":"a contingency plan for the system is developed that addresses the sharing of contingency information;"},{"id":"cp-2_obj.a.7-1","label":"CP-02a.07[01]","text":"a contingency plan for the system is developed that is reviewed by {{ insert: param, cp-02_odp.01 }};"},{"id":"cp-2_obj.a.7-2","label":"CP-02a.07[02]","text":"a contingency plan for the system is developed that is approved by {{ insert: param, cp-02_odp.02 }};"},{"id":"cp-2_obj.b-1","label":"CP-02b.[01]","text":"copies of the contingency plan are distributed to {{ insert: param, cp-02_odp.03 }};"},{"id":"cp-2_obj.b-2","label":"CP-02b.[02]","text":"copies of the contingency plan are distributed to {{ insert: param, cp-02_odp.04 }};"},{"id":"cp-2_obj.c","label":"CP-02c.","text":"contingency planning activities are coordinated with incident handling activities;"},{"id":"cp-2_obj.d","label":"CP-02d.","text":"the contingency plan for the system is reviewed {{ insert: param, cp-02_odp.05 }};"},{"id":"cp-2_obj.e-1","label":"CP-02e.[01]","text":"the contingency plan is updated to address changes to the organization, system, or environment of operation;"},{"id":"cp-2_obj.e-2","label":"CP-02e.[02]","text":"the contingency plan is updated to address problems encountered during contingency plan implementation, execution, or testing;"},{"id":"cp-2_obj.f-1","label":"CP-02f.[01]","text":"contingency plan changes are communicated to {{ insert: param, cp-02_odp.06 }};"},{"id":"cp-2_obj.f-2","label":"CP-02f.[02]","text":"contingency plan changes are communicated to {{ insert: param, cp-02_odp.07 }};"},{"id":"cp-2_obj.g-1","label":"CP-02g.[01]","text":"lessons learned from contingency plan testing or actual contingency activities are incorporated into contingency testing;"},{"id":"cp-2_obj.g-2","label":"CP-02g.[02]","text":"lessons learned from contingency plan training or actual contingency activities are incorporated into contingency testing and training;"},{"id":"cp-2_obj.h-1","label":"CP-02h.[01]","text":"the contingency plan is protected from unauthorized disclosure;"},{"id":"cp-2_obj.h-2","label":"CP-02h.[02]","text":"the contingency plan is protected from unauthorized modification."}],"methods":[{"method":"examine","label":"CP-02-Examine"},{"method":"interview","label":"CP-02-Interview"},{"method":"test","label":"CP-02-Test"}],"references":[{"title":"SP 800-34"},{"title":"IR 8179"}],"related_controls":["CP-3","CP-4","CP-6","CP-7","CP-8","CP-9","CP-10","CP-11","CP-13","IR-4","IR-6","IR-8","IR-9","MA-6","MP-2","MP-4","MP-5","PL-2","PM-8","PM-11","SA-15","SA-20","SC-7","SC-23","SI-12"],"enhancements":[{"id":"CP-2(1)","oscal_id":"cp-2.1","family":"CP","title":"Coordinate with Related Plans","statement":"Coordinate contingency plan development with organizational elements responsible for related plans.","supplemental_guidance":"Plans that are related to contingency plans include Business Continuity Plans, Disaster Recovery Plans, Critical Infrastructure Plans, Continuity of Operations Plans, Crisis Communications Plans, Insider Threat Implementation Plans, Data Breach Response Plans, Cyber Incident Response Plans, Breach Response Plans, and Occupant Emergency Plans.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-02(01)-Examine"},{"method":"interview","label":"CP-02(01)-Interview"}],"is_enhancement":true,"parent_id":"CP-2"},{"id":"CP-2(2)","oscal_id":"cp-2.2","family":"CP","title":"Capacity Planning","statement":"Conduct capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations.","supplemental_guidance":"Capacity planning is needed because different threats can result in a reduction of the available processing, telecommunications, and support services intended to support essential mission and business functions. Organizations anticipate degraded operations during contingency operations and factor the degradation into capacity planning. For capacity planning, environmental support refers to any environmental factor for which the organization determines that it needs to provide support in a contingency situation, even if in a degraded state. Such determinations are based on an organizational assessment of risk, system categorization (impact level), and organizational risk tolerance.","implementation_level":"organization","objectives":[{"id":"cp-2.2_obj-1","label":"CP-02(02)[01]","text":"capacity planning is conducted so that the necessary capacity exists during contingency operations for information processing;"},{"id":"cp-2.2_obj-2","label":"CP-02(02)[02]","text":"capacity planning is conducted so that the necessary capacity exists during contingency operations for telecommunications;"},{"id":"cp-2.2_obj-3","label":"CP-02(02)[03]","text":"capacity planning is conducted so that the necessary capacity exists during contingency operations for environmental support."}],"methods":[{"method":"examine","label":"CP-02(02)-Examine"},{"method":"interview","label":"CP-02(02)-Interview"}],"related_controls":["PE-11","PE-12","PE-13","PE-14","PE-18","SC-5"],"is_enhancement":true,"parent_id":"CP-2"},{"id":"CP-2(3)","oscal_id":"cp-2.3","family":"CP","title":"Resume Mission and Business Functions","statement":"Plan for the resumption of <organization-defined parameter> mission and business functions within <time period> of contingency plan activation.","supplemental_guidance":"Organizations may choose to conduct contingency planning activities to resume mission and business functions as part of business continuity planning or as part of business impact analyses. Organizations prioritize the resumption of mission and business functions. The time period for resuming mission and business functions may be dependent on the severity and extent of the disruptions to the system and its supporting infrastructure.","implementation_level":"organization","parameters":[{"id":"cp-02.03_odp.01","label":"","choices":["all","essential"]},{"id":"cp-02.03_odp.02","label":"time period"}],"methods":[{"method":"examine","label":"CP-02(03)-Examine"},{"method":"interview","label":"CP-02(03)-Interview"},{"method":"test","label":"CP-02(03)-Test"}],"is_enhancement":true,"parent_id":"CP-2"},{"id":"CP-2(4)","oscal_id":"cp-2.4","family":"CP","title":"Resume All Mission and Business Functions","statement":"","is_enhancement":true,"parent_id":"CP-2"},{"id":"CP-2(5)","oscal_id":"cp-2.5","family":"CP","title":"Continue Mission and Business Functions","statement":"Plan for the continuance of <organization-defined parameter> mission and business functions with minimal or no loss of operational continuity and sustains that continuity until full system restoration at primary processing and/or storage sites.","supplemental_guidance":"Organizations may choose to conduct the contingency planning activities to continue mission and business functions as part of business continuity planning or business impact analyses. Primary processing and/or storage sites defined by organizations as part of contingency planning may change depending on the circumstances associated with the contingency.","implementation_level":"organization","parameters":[{"id":"cp-02.05_odp","label":"","choices":["all","essential"]}],"objectives":[{"id":"cp-2.5_obj-1","label":"CP-02(05)[01]","text":"the continuance of {{ insert: param, cp-02.05_odp }} mission and business functions with minimal or no loss of operational continuity is planned for;"},{"id":"cp-2.5_obj-2","label":"CP-02(05)[02]","text":"continuity is sustained until full system restoration at primary processing and/or storage sites."}],"methods":[{"method":"examine","label":"CP-02(05)-Examine"},{"method":"interview","label":"CP-02(05)-Interview"},{"method":"test","label":"CP-02(05)-Test"}],"is_enhancement":true,"parent_id":"CP-2"},{"id":"CP-2(6)","oscal_id":"cp-2.6","family":"CP","title":"Alternate Processing and Storage Sites","statement":"Plan for the transfer of <organization-defined parameter> mission and business functions to alternate processing and/or storage sites with minimal or no loss of operational continuity and sustain that continuity through system restoration to primary processing and/or storage sites.","supplemental_guidance":"Organizations may choose to conduct contingency planning activities for alternate processing and storage sites as part of business continuity planning or business impact analyses. Primary processing and/or storage sites defined by organizations as part of contingency planning may change depending on the circumstances associated with the contingency.","implementation_level":"organization","parameters":[{"id":"cp-02.06_odp","label":"","choices":["all","essential"]}],"objectives":[{"id":"cp-2.6_obj-1","label":"CP-02(06)[01]","text":"the transfer of {{ insert: param, cp-02.06_odp }} mission and business functions to alternate processing and/or storage sites with minimal or no loss of operational continuity is planned for;"},{"id":"cp-2.6_obj-2","label":"CP-02(06)[02]","text":"operational continuity is sustained until full system restoration at primary processing and/or storage sites."}],"methods":[{"method":"examine","label":"CP-02(06)-Examine"},{"method":"interview","label":"CP-02(06)-Interview"},{"method":"test","label":"CP-02(06)-Test"}],"is_enhancement":true,"parent_id":"CP-2"},{"id":"CP-2(7)","oscal_id":"cp-2.7","family":"CP","title":"Coordinate with External Service Providers","statement":"Coordinate the contingency plan with the contingency plans of external service providers to ensure that contingency requirements can be satisfied.","supplemental_guidance":"When the capability of an organization to carry out its mission and business functions is dependent on external service providers, developing a comprehensive and timely contingency plan may become more challenging. When mission and business functions are dependent on external service providers, organizations coordinate contingency planning activities with the external entities to ensure that the individual plans reflect the overall contingency needs of the organization.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-02(07)-Examine"},{"method":"interview","label":"CP-02(07)-Interview"}],"related_controls":["SA-9"],"is_enhancement":true,"parent_id":"CP-2"},{"id":"CP-2(8)","oscal_id":"cp-2.8","family":"CP","title":"Identify Critical Assets","statement":"Identify critical system assets supporting <organization-defined parameter> mission and business functions.","supplemental_guidance":"Organizations may choose to identify critical assets as part of criticality analysis, business continuity planning, or business impact analyses. Organizations identify critical system assets so that additional controls can be employed (beyond the controls routinely implemented) to help ensure that organizational mission and business functions can continue to be conducted during contingency operations. The identification of critical information assets also facilitates the prioritization of organizational resources. Critical system assets include technical and operational aspects. Technical aspects include system components, information technology services, information technology products, and mechanisms. Operational aspects include procedures (i.e., manually executed operations) and personnel (i.e., individuals operating technical controls and/or executing manual procedures). Organizational program protection plans can assist in identifying critical assets. If critical assets are resident within or supported by external service providers, organizations consider implementing [CP-2(7)](#cp-2.7) as a control enhancement.","implementation_level":"organization","parameters":[{"id":"cp-02.08_odp","label":"","choices":["all","essential"]}],"methods":[{"method":"examine","label":"CP-02(08)-Examine"},{"method":"interview","label":"CP-02(08)-Interview"}],"related_controls":["CM-8","RA-9"],"is_enhancement":true,"parent_id":"CP-2"}]},{"id":"CP-3","oscal_id":"cp-3","family":"CP","title":"Contingency Training","statement":"a. Provide contingency training to system users consistent with assigned roles and responsibilities:\n  Provide contingency training to system users consistent with assigned roles and responsibilities:\n  1. Within <time period> of assuming a contingency role or responsibility;\n  2. When required by system changes; and\n  3. <frequency> thereafter; and\nb. Review and update contingency training content <frequency> and following <events>.","supplemental_guidance":"Contingency training provided by organizations is linked to the assigned roles and responsibilities of organizational personnel to ensure that the appropriate content and level of detail is included in such training. For example, some individuals may only need to know when and where to report for duty during contingency operations and if normal duties are affected; system administrators may require additional training on how to establish systems at alternate processing and storage sites; and organizational officials may receive more specific training on how to conduct mission-essential functions in designated off-site locations and how to establish communications with other governmental entities for purposes of coordination on contingency-related activities. Training for contingency roles or responsibilities reflects the specific continuity requirements in the contingency plan. Events that may precipitate an update to contingency training content include, but are not limited to, contingency plan testing or an actual contingency (lessons learned), assessment or audit findings, security incidents or breaches, or changes in laws, executive orders, directives, regulations, policies, standards, and guidelines. At the discretion of the organization, participation in a contingency plan test or exercise, including lessons learned sessions subsequent to the test or exercise, may satisfy contingency plan training requirements.","implementation_level":"organization","parameters":[{"id":"cp-03_odp.01","label":"time period"},{"id":"cp-03_odp.02","label":"frequency"},{"id":"cp-03_odp.03","label":"frequency"},{"id":"cp-03_odp.04","label":"events"}],"objectives":[{"id":"cp-3_obj.a.1","label":"CP-03a.01","text":"contingency training is provided to system users consistent with assigned roles and responsibilities within {{ insert: param, cp-03_odp.01 }} of assuming a contingency role or responsibility;"},{"id":"cp-3_obj.a.2","label":"CP-03a.02","text":"contingency training is provided to system users consistent with assigned roles and responsibilities when required by system changes;"},{"id":"cp-3_obj.a.3","label":"CP-03a.03","text":"contingency training is provided to system users consistent with assigned roles and responsibilities {{ insert: param, cp-03_odp.02 }} thereafter;"},{"id":"cp-3_obj.b-1","label":"CP-03b.[01]","text":"the contingency plan training content is reviewed and updated {{ insert: param, cp-03_odp.03 }};"},{"id":"cp-3_obj.b-2","label":"CP-03b.[02]","text":"the contingency plan training content is reviewed and updated following {{ insert: param, cp-03_odp.04 }}."}],"methods":[{"method":"examine","label":"CP-03-Examine"},{"method":"interview","label":"CP-03-Interview"},{"method":"test","label":"CP-03-Test"}],"references":[{"title":"SP 800-50"}],"related_controls":["AT-2","AT-3","AT-4","CP-2","CP-4","CP-8","IR-2","IR-4","IR-9"],"enhancements":[{"id":"CP-3(1)","oscal_id":"cp-3.1","family":"CP","title":"Simulated Events","statement":"Incorporate simulated events into contingency training to facilitate effective response by personnel in crisis situations.","supplemental_guidance":"The use of simulated events creates an environment for personnel to experience actual threat events, including cyber-attacks that disable websites, ransomware attacks that encrypt organizational data on servers, hurricanes that damage or destroy organizational facilities, or hardware or software failures.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-03(01)-Examine"},{"method":"interview","label":"CP-03(01)-Interview"},{"method":"test","label":"CP-03(01)-Test"}],"is_enhancement":true,"parent_id":"CP-3"},{"id":"CP-3(2)","oscal_id":"cp-3.2","family":"CP","title":"Mechanisms Used in Training Environments","statement":"Employ mechanisms used in operations to provide a more thorough and realistic contingency training environment.","supplemental_guidance":"Operational mechanisms refer to processes that have been established to accomplish an organizational goal or a system that supports a particular organizational mission or business objective. Actual mission and business processes, systems, and/or facilities may be used to generate simulated events and enhance the realism of simulated events during contingency training.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-03(02)-Examine"},{"method":"interview","label":"CP-03(02)-Interview"},{"method":"test","label":"CP-03(02)-Test"}],"is_enhancement":true,"parent_id":"CP-3"}]},{"id":"CP-4","oscal_id":"cp-4","family":"CP","title":"Contingency Plan Testing","statement":"a. Test the contingency plan for the system <frequency> using the following tests to determine the effectiveness of the plan and the readiness to execute the plan: <organization-defined tests>.\nb. Review the contingency plan test results; and\nc. Initiate corrective actions, if needed.","supplemental_guidance":"Methods for testing contingency plans to determine the effectiveness of the plans and identify potential weaknesses include checklists, walk-through and tabletop exercises, simulations (parallel or full interrupt), and comprehensive exercises. Organizations conduct testing based on the requirements in contingency plans and include a determination of the effects on organizational operations, assets, and individuals due to contingency operations. Organizations have flexibility and discretion in the breadth, depth, and timelines of corrective actions.","implementation_level":"organization","parameters":[{"id":"cp-4_prm_2","label":"organization-defined tests"},{"id":"cp-04_odp.01","label":"frequency"},{"id":"cp-04_odp.02","label":"tests"},{"id":"cp-04_odp.03","label":"tests"}],"objectives":[{"id":"cp-4_obj.a-1","label":"CP-04a.[01]","text":"the contingency plan for the system is tested {{ insert: param, cp-04_odp.01 }};"},{"id":"cp-4_obj.a-2","label":"CP-04a.[02]","text":"{{ insert: param, cp-04_odp.02 }} are used to determine the effectiveness of the plan;"},{"id":"cp-4_obj.a-3","label":"CP-04a.[03]","text":"{{ insert: param, cp-04_odp.03 }} are used to determine the readiness to execute the plan;"},{"id":"cp-4_obj.b","label":"CP-04b.","text":"the contingency plan test results are reviewed;"},{"id":"cp-4_obj.c","label":"CP-04c.","text":"corrective actions are initiated, if needed."}],"methods":[{"method":"examine","label":"CP-04-Examine"},{"method":"interview","label":"CP-04-Interview"},{"method":"test","label":"CP-04-Test"}],"references":[{"title":"FIPS 199"},{"title":"SP 800-34"},{"title":"SP 800-84"},{"title":"SP 800-160-2"}],"related_controls":["AT-3","CP-2","CP-3","CP-8","CP-9","IR-3","IR-4","PL-2","PM-14","SR-2"],"enhancements":[{"id":"CP-4(1)","oscal_id":"cp-4.1","family":"CP","title":"Coordinate with Related Plans","statement":"Coordinate contingency plan testing with organizational elements responsible for related plans.","supplemental_guidance":"Plans related to contingency planning for organizational systems include Business Continuity Plans, Disaster Recovery Plans, Continuity of Operations Plans, Crisis Communications Plans, Critical Infrastructure Plans, Cyber Incident Response Plans, and Occupant Emergency Plans. Coordination of contingency plan testing does not require organizations to create organizational elements to handle related plans or to align such elements with specific plans. However, it does require that if such organizational elements are responsible for related plans, organizations coordinate with those elements.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-04(01)-Examine"},{"method":"interview","label":"CP-04(01)-Interview"}],"related_controls":["IR-8","PM-8"],"is_enhancement":true,"parent_id":"CP-4"},{"id":"CP-4(2)","oscal_id":"cp-4.2","family":"CP","title":"Alternate Processing Site","statement":"Test the contingency plan at the alternate processing site:\n(a) To familiarize contingency personnel with the facility and available resources; and\n(b) To evaluate the capabilities of the alternate processing site to support contingency operations.","supplemental_guidance":"Conditions at the alternate processing site may be significantly different than the conditions at the primary site. Having the opportunity to visit the alternate site and experience the actual capabilities available at the site can provide valuable information on potential vulnerabilities that could affect essential organizational mission and business functions. The on-site visit can also provide an opportunity to refine the contingency plan to address the vulnerabilities discovered during testing.","implementation_level":"organization","objectives":[{"id":"cp-4.2_obj.a","label":"CP-04(02)(a)","text":"the contingency plan is tested at the alternate processing site to familiarize contingency personnel with the facility and available resources;"},{"id":"cp-4.2_obj.b","label":"CP-04(02)(b)","text":"the contingency plan is tested at the alternate processing site to evaluate the capabilities of the alternate processing site to support contingency operations."}],"methods":[{"method":"examine","label":"CP-04(02)-Examine"},{"method":"interview","label":"CP-04(02)-Interview"},{"method":"test","label":"CP-04(02)-Test"}],"related_controls":["CP-7"],"is_enhancement":true,"parent_id":"CP-4"},{"id":"CP-4(3)","oscal_id":"cp-4.3","family":"CP","title":"Automated Testing","statement":"Test the contingency plan using <automated mechanisms>.","supplemental_guidance":"Automated mechanisms facilitate thorough and effective testing of contingency plans by providing more complete coverage of contingency issues, selecting more realistic test scenarios and environments, and effectively stressing the system and supported mission and business functions.","implementation_level":"organization","parameters":[{"id":"cp-04.03_odp","label":"automated mechanisms"}],"methods":[{"method":"examine","label":"CP-04(03)-Examine"},{"method":"interview","label":"CP-04(03)-Interview"},{"method":"test","label":"CP-04(03)-Test"}],"is_enhancement":true,"parent_id":"CP-4"},{"id":"CP-4(4)","oscal_id":"cp-4.4","family":"CP","title":"Full Recovery and Reconstitution","statement":"Include a full recovery and reconstitution of the system to a known state as part of contingency plan testing.","supplemental_guidance":"Recovery is executing contingency plan activities to restore organizational mission and business functions. Reconstitution takes place following recovery and includes activities for returning systems to fully operational states. Organizations establish a known state for systems that includes system state information for hardware, software programs, and data. Preserving system state information facilitates system restart and return to the operational mode of organizations with less disruption of mission and business processes.","implementation_level":"organization","objectives":[{"id":"cp-4.4_obj-1","label":"CP-04(04)[01]","text":"a full recovery of the system to a known state is included as part of contingency plan testing;"},{"id":"cp-4.4_obj-2","label":"CP-04(04)[02]","text":"a full reconstitution of the system to a known state is included as part of contingency plan testing."}],"methods":[{"method":"examine","label":"CP-04(04)-Examine"},{"method":"interview","label":"CP-04(04)-Interview"},{"method":"test","label":"CP-04(04)-Test"}],"related_controls":["CP-10","SC-24"],"is_enhancement":true,"parent_id":"CP-4"},{"id":"CP-4(5)","oscal_id":"cp-4.5","family":"CP","title":"Self-challenge","statement":"Employ <mechanisms> to <system or system component> to disrupt and adversely affect the system or system component.","supplemental_guidance":"Often, the best method of assessing system resilience is to disrupt the system in some manner. The mechanisms used by the organization could disrupt system functions or system services in many ways, including terminating or disabling critical system components, changing the configuration of system components, degrading critical functionality (e.g., restricting network bandwidth), or altering privileges. Automated, on-going, and simulated cyber-attacks and service disruptions can reveal unexpected functional dependencies and help the organization determine its ability to ensure resilience in the face of an actual cyber-attack.","implementation_level":"organization","parameters":[{"id":"cp-04.05_odp.01","label":"mechanisms"},{"id":"cp-04.05_odp.02","label":"system or system component"}],"methods":[{"method":"examine","label":"CP-04(05)-Examine"},{"method":"interview","label":"CP-04(05)-Interview"},{"method":"test","label":"CP-04(05)-Test"}],"is_enhancement":true,"parent_id":"CP-4"}]},{"id":"CP-5","oscal_id":"cp-5","family":"CP","title":"Contingency Plan Update","statement":""},{"id":"CP-6","oscal_id":"cp-6","family":"CP","title":"Alternate Storage Site","statement":"a. Establish an alternate storage site, including necessary agreements to permit the storage and retrieval of system backup information; and\nb. Ensure that the alternate storage site provides controls equivalent to that of the primary site.","supplemental_guidance":"Alternate storage sites are geographically distinct from primary storage sites and maintain duplicate copies of information and data if the primary storage site is not available. Similarly, alternate processing sites provide processing capability if the primary processing site is not available. Geographically distributed architectures that support contingency requirements may be considered alternate storage sites. Items covered by alternate storage site agreements include environmental conditions at the alternate sites, access rules for systems and facilities, physical and environmental protection requirements, and coordination of delivery and retrieval of backup media. Alternate storage sites reflect the requirements in contingency plans so that organizations can maintain essential mission and business functions despite compromise, failure, or disruption in organizational systems.","implementation_level":"organization","objectives":[{"id":"cp-6_obj.a-1","label":"CP-06a.[01]","text":"an alternate storage site is established;"},{"id":"cp-6_obj.a-2","label":"CP-06a.[02]","text":"establishment of the alternate storage site includes necessary agreements to permit the storage and retrieval of system backup information;"},{"id":"cp-6_obj.b","label":"CP-06b.","text":"the alternate storage site provides controls equivalent to that of the primary site."}],"methods":[{"method":"examine","label":"CP-06-Examine"},{"method":"interview","label":"CP-06-Interview"},{"method":"test","label":"CP-06-Test"}],"references":[{"title":"SP 800-34"}],"related_controls":["CP-2","CP-7","CP-8","CP-9","CP-10","MP-4","MP-5","PE-3","SC-36","SI-13"],"enhancements":[{"id":"CP-6(1)","oscal_id":"cp-6.1","family":"CP","title":"Separation from Primary Site","statement":"Identify an alternate storage site that is sufficiently separated from the primary storage site to reduce susceptibility to the same threats.","supplemental_guidance":"Threats that affect alternate storage sites are defined in organizational risk assessments and include natural disasters, structural failures, hostile attacks, and errors of omission or commission. Organizations determine what is considered a sufficient degree of separation between primary and alternate storage sites based on the types of threats that are of concern. For threats such as hostile attacks, the degree of separation between sites is less relevant.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-06(01)-Examine"},{"method":"interview","label":"CP-06(01)-Interview"}],"related_controls":["RA-3"],"is_enhancement":true,"parent_id":"CP-6"},{"id":"CP-6(2)","oscal_id":"cp-6.2","family":"CP","title":"Recovery Time and Recovery Point Objectives","statement":"Configure the alternate storage site to facilitate recovery operations in accordance with recovery time and recovery point objectives.","supplemental_guidance":"Organizations establish recovery time and recovery point objectives as part of contingency planning. Configuration of the alternate storage site includes physical facilities and the systems supporting recovery operations that ensure accessibility and correct execution.","implementation_level":"organization","objectives":[{"id":"cp-6.2_obj-1","label":"CP-06(02)[01]","text":"the alternate storage site is configured to facilitate recovery operations in accordance with recovery time objectives;"},{"id":"cp-6.2_obj-2","label":"CP-06(02)[02]","text":"the alternate storage site is configured to facilitate recovery operations in accordance with recovery point objectives."}],"methods":[{"method":"examine","label":"CP-06(02)-Examine"},{"method":"interview","label":"CP-06(02)-Interview"},{"method":"test","label":"CP-06(02)-Test"}],"is_enhancement":true,"parent_id":"CP-6"},{"id":"CP-6(3)","oscal_id":"cp-6.3","family":"CP","title":"Accessibility","statement":"Identify potential accessibility problems to the alternate storage site in the event of an area-wide disruption or disaster and outline explicit mitigation actions.","supplemental_guidance":"Area-wide disruptions refer to those types of disruptions that are broad in geographic scope with such determinations made by organizations based on organizational assessments of risk. Explicit mitigation actions include duplicating backup information at other alternate storage sites if access problems occur at originally designated alternate sites or planning for physical access to retrieve backup information if electronic accessibility to the alternate site is disrupted.","implementation_level":"organization","objectives":[{"id":"cp-6.3_obj-1","label":"CP-06(03)[01]","text":"potential accessibility problems to the alternate storage site in the event of an area-wide disruption or disaster are identified;"},{"id":"cp-6.3_obj-2","label":"CP-06(03)[02]","text":"explicit mitigation actions to address identified accessibility problems are outlined."}],"methods":[{"method":"examine","label":"CP-06(03)-Examine"},{"method":"interview","label":"CP-06(03)-Interview"}],"related_controls":["RA-3"],"is_enhancement":true,"parent_id":"CP-6"}]},{"id":"CP-7","oscal_id":"cp-7","family":"CP","title":"Alternate Processing Site","statement":"a. Establish an alternate processing site, including necessary agreements to permit the transfer and resumption of <system operations> for essential mission and business functions within <time period> when the primary processing capabilities are unavailable;\nb. Make available at the alternate processing site, the equipment and supplies required to transfer and resume operations or put contracts in place to support delivery to the site within the organization-defined time period for transfer and resumption; and\nc. Provide controls at the alternate processing site that are equivalent to those at the primary site.","supplemental_guidance":"Alternate processing sites are geographically distinct from primary processing sites and provide processing capability if the primary processing site is not available. The alternate processing capability may be addressed using a physical processing site or other alternatives, such as failover to a cloud-based service provider or other internally or externally provided processing service. Geographically distributed architectures that support contingency requirements may also be considered alternate processing sites. Controls that are covered by alternate processing site agreements include the environmental conditions at alternate sites, access rules, physical and environmental protection requirements, and the coordination for the transfer and assignment of personnel. Requirements are allocated to alternate processing sites that reflect the requirements in contingency plans to maintain essential mission and business functions despite disruption, compromise, or failure in organizational systems.","implementation_level":"organization","parameters":[{"id":"cp-07_odp.01","label":"system operations"},{"id":"cp-07_odp.02","label":"time period"}],"objectives":[{"id":"cp-7_obj.a","label":"CP-07a.","text":"an alternate processing site, including necessary agreements to permit the transfer and resumption of {{ insert: param, cp-07_odp.01 }} for essential mission and business functions, is established within {{ insert: param, cp-07_odp.02 }} when the primary processing capabilities are unavailable;"},{"id":"cp-7_obj.b-1","label":"CP-07b.[01]","text":"the equipment and supplies required to transfer operations are made available at the alternate processing site or if contracts are in place to support delivery to the site within {{ insert: param, cp-07_odp.02 }} for transfer;"},{"id":"cp-7_obj.b-2","label":"CP-07b.[02]","text":"the equipment and supplies required to resume operations are made available at the alternate processing site or if contracts are in place to support delivery to the site within {{ insert: param, cp-07_odp.02 }} for resumption;"},{"id":"cp-7_obj.c","label":"CP-07c.","text":"controls provided at the alternate processing site are equivalent to those at the primary site."}],"methods":[{"method":"examine","label":"CP-07-Examine"},{"method":"interview","label":"CP-07-Interview"},{"method":"test","label":"CP-07-Test"}],"references":[{"title":"SP 800-34"}],"related_controls":["CP-2","CP-6","CP-8","CP-9","CP-10","MA-6","PE-3","PE-11","PE-12","PE-17","SC-36","SI-13"],"enhancements":[{"id":"CP-7(1)","oscal_id":"cp-7.1","family":"CP","title":"Separation from Primary Site","statement":"Identify an alternate processing site that is sufficiently separated from the primary processing site to reduce susceptibility to the same threats.","supplemental_guidance":"Threats that affect alternate processing sites are defined in organizational assessments of risk and include natural disasters, structural failures, hostile attacks, and errors of omission or commission. Organizations determine what is considered a sufficient degree of separation between primary and alternate processing sites based on the types of threats that are of concern. For threats such as hostile attacks, the degree of separation between sites is less relevant.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-07(01)-Examine"},{"method":"interview","label":"CP-07(01)-Interview"}],"related_controls":["RA-3"],"is_enhancement":true,"parent_id":"CP-7"},{"id":"CP-7(2)","oscal_id":"cp-7.2","family":"CP","title":"Accessibility","statement":"Identify potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster and outlines explicit mitigation actions.","supplemental_guidance":"Area-wide disruptions refer to those types of disruptions that are broad in geographic scope with such determinations made by organizations based on organizational assessments of risk.","implementation_level":"organization","objectives":[{"id":"cp-7.2_obj-1","label":"CP-07(02)[01]","text":"potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster are identified;"},{"id":"cp-7.2_obj-2","label":"CP-07(02)[02]","text":"explicit mitigation actions to address identified accessibility problems are outlined."}],"methods":[{"method":"examine","label":"CP-07(02)-Examine"},{"method":"interview","label":"CP-07(02)-Interview"}],"related_controls":["RA-3"],"is_enhancement":true,"parent_id":"CP-7"},{"id":"CP-7(3)","oscal_id":"cp-7.3","family":"CP","title":"Priority of Service","statement":"Develop alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives).","supplemental_guidance":"Priority of service agreements refer to negotiated agreements with service providers that ensure that organizations receive priority treatment consistent with their availability requirements and the availability of information resources for logical alternate processing and/or at the physical alternate processing site. Organizations establish recovery time objectives as part of contingency planning.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-07(03)-Examine"},{"method":"interview","label":"CP-07(03)-Interview"}],"is_enhancement":true,"parent_id":"CP-7"},{"id":"CP-7(4)","oscal_id":"cp-7.4","family":"CP","title":"Preparation for Use","statement":"Prepare the alternate processing site so that the site can serve as the operational site supporting essential mission and business functions.","supplemental_guidance":"Site preparation includes establishing configuration settings for systems at the alternate processing site consistent with the requirements for such settings at the primary site and ensuring that essential supplies and logistical considerations are in place.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-07(04)-Examine"},{"method":"interview","label":"CP-07(04)-Interview"},{"method":"test","label":"CP-07(04)-Test"}],"related_controls":["CM-2","CM-6","CP-4"],"is_enhancement":true,"parent_id":"CP-7"},{"id":"CP-7(5)","oscal_id":"cp-7.5","family":"CP","title":"Equivalent Information Security Safeguards","statement":"","is_enhancement":true,"parent_id":"CP-7"},{"id":"CP-7(6)","oscal_id":"cp-7.6","family":"CP","title":"Inability to Return to Primary Site","statement":"Plan and prepare for circumstances that preclude returning to the primary processing site.","supplemental_guidance":"There may be situations that preclude an organization from returning to the primary processing site such as if a natural disaster (e.g., flood or a hurricane) damaged or destroyed a facility and it was determined that rebuilding in the same location was not prudent.","implementation_level":"organization","objectives":[{"id":"cp-7.6_obj-1","label":"CP-07(06)[01]","text":"circumstances that preclude returning to the primary processing site are planned for;"},{"id":"cp-7.6_obj-2","label":"CP-07(06)[02]","text":"circumstances that preclude returning to the primary processing site are prepared for."}],"methods":[{"method":"examine","label":"CP-07(06)-Examine"},{"method":"interview","label":"CP-07(06)-Interview"}],"is_enhancement":true,"parent_id":"CP-7"}]},{"id":"CP-8","oscal_id":"cp-8","family":"CP","title":"Telecommunications Services","statement":"Establish alternate telecommunications services, including necessary agreements to permit the resumption of <system operations> for essential mission and business functions within <time period> when the primary telecommunications capabilities are unavailable at either the primary or alternate processing or storage sites.","supplemental_guidance":"Telecommunications services (for data and voice) for primary and alternate processing and storage sites are in scope for [CP-8](#cp-8) . Alternate telecommunications services reflect the continuity requirements in contingency plans to maintain essential mission and business functions despite the loss of primary telecommunications services. Organizations may specify different time periods for primary or alternate sites. Alternate telecommunications services include additional organizational or commercial ground-based circuits or lines, network-based approaches to telecommunications, or the use of satellites. Organizations consider factors such as availability, quality of service, and access when entering into alternate telecommunications agreements.","implementation_level":"organization","parameters":[{"id":"cp-08_odp.01","label":"system operations"},{"id":"cp-08_odp.02","label":"time period"}],"methods":[{"method":"examine","label":"CP-08-Examine"},{"method":"interview","label":"CP-08-Interview"},{"method":"test","label":"CP-08-Test"}],"references":[{"title":"SP 800-34"}],"related_controls":["CP-2","CP-6","CP-7","CP-11","SC-7"],"enhancements":[{"id":"CP-8(1)","oscal_id":"cp-8.1","family":"CP","title":"Priority of Service Provisions","statement":"(a) Develop primary and alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives); and\n(b) Request Telecommunications Service Priority for all telecommunications services used for national security emergency preparedness if the primary and/or alternate telecommunications services are provided by a common carrier.","supplemental_guidance":"Organizations consider the potential mission or business impact in situations where telecommunications service providers are servicing other organizations with similar priority of service provisions. Telecommunications Service Priority (TSP) is a Federal Communications Commission (FCC) program that directs telecommunications service providers (e.g., wireline and wireless phone companies) to give preferential treatment to users enrolled in the program when they need to add new lines or have their lines restored following a disruption of service, regardless of the cause. The FCC sets the rules and policies for the TSP program, and the Department of Homeland Security manages the TSP program. The TSP program is always in effect and not contingent on a major disaster or attack taking place. Federal sponsorship is required to enroll in the TSP program.","implementation_level":"organization","objectives":[{"id":"cp-8.1_obj.a-1","label":"CP-08(01)(a)[01]","text":"primary telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives) are developed;"},{"id":"cp-8.1_obj.a-2","label":"CP-08(01)(a)[02]","text":"alternate telecommunications service agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives) are developed;"},{"id":"cp-8.1_obj.b","label":"CP-08(01)(b)","text":"Telecommunications Service Priority is requested for all telecommunications services used for national security emergency preparedness if the primary and/or alternate telecommunications services are provided by a common carrier."}],"methods":[{"method":"examine","label":"CP-08(01)-Examine"},{"method":"interview","label":"CP-08(01)-Interview"},{"method":"test","label":"CP-08(01)-Test"}],"is_enhancement":true,"parent_id":"CP-8"},{"id":"CP-8(2)","oscal_id":"cp-8.2","family":"CP","title":"Single Points of Failure","statement":"Obtain alternate telecommunications services to reduce the likelihood of sharing a single point of failure with primary telecommunications services.","supplemental_guidance":"In certain circumstances, telecommunications service providers or services may share the same physical lines, which increases the vulnerability of a single failure point. It is important to have provider transparency for the actual physical transmission capability for telecommunication services.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-08(02)-Examine"},{"method":"interview","label":"CP-08(02)-Interview"}],"is_enhancement":true,"parent_id":"CP-8"},{"id":"CP-8(3)","oscal_id":"cp-8.3","family":"CP","title":"Separation of Primary and Alternate Providers","statement":"Obtain alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats.","supplemental_guidance":"Threats that affect telecommunications services are defined in organizational assessments of risk and include natural disasters, structural failures, cyber or physical attacks, and errors of omission or commission. Organizations can reduce common susceptibilities by minimizing shared infrastructure among telecommunications service providers and achieving sufficient geographic separation between services. Organizations may consider using a single service provider in situations where the service provider can provide alternate telecommunications services that meet the separation needs addressed in the risk assessment.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-08(03)-Examine"},{"method":"interview","label":"CP-08(03)-Interview"}],"is_enhancement":true,"parent_id":"CP-8"},{"id":"CP-8(4)","oscal_id":"cp-8.4","family":"CP","title":"Provider Contingency Plan","statement":"(a) Require primary and alternate telecommunications service providers to have contingency plans;\n(b) Review provider contingency plans to ensure that the plans meet organizational contingency requirements; and\n(c) Obtain evidence of contingency testing and training by providers <organization-defined frequency>.","supplemental_guidance":"Reviews of provider contingency plans consider the proprietary nature of such plans. In some situations, a summary of provider contingency plans may be sufficient evidence for organizations to satisfy the review requirement. Telecommunications service providers may also participate in ongoing disaster recovery exercises in coordination with the Department of Homeland Security and state and local governments. Organizations may use these types of activities to satisfy evidentiary requirements related to service provider contingency plan reviews, testing, and training.","implementation_level":"organization","parameters":[{"id":"cp-8.4_prm_1","label":"organization-defined frequency"},{"id":"cp-08.04_odp.01","label":"frequency"},{"id":"cp-08.04_odp.02","label":"frequency"}],"objectives":[{"id":"cp-8.4_obj.a-1","label":"CP-08(04)(a)[01]","text":"primary telecommunications service providers are required to have contingency plans;"},{"id":"cp-8.4_obj.a-2","label":"CP-08(04)(a)[02]","text":"alternate telecommunications service providers are required to have contingency plans;"},{"id":"cp-8.4_obj.b","label":"CP-08(04)(b)","text":"provider contingency plans are reviewed to ensure that the plans meet organizational contingency requirements;"},{"id":"cp-8.4_obj.c-1","label":"CP-08(04)(c)[01]","text":"evidence of contingency testing by providers is obtained {{ insert: param, cp-08.04_odp.01 }}."},{"id":"cp-8.4_obj.c-2","label":"CP-08(04)(c)[02]","text":"evidence of contingency training by providers is obtained {{ insert: param, cp-08.04_odp.02 }}."}],"methods":[{"method":"examine","label":"CP-08(04)-Examine"},{"method":"interview","label":"CP-08(04)-Interview"}],"related_controls":["CP-3","CP-4"],"is_enhancement":true,"parent_id":"CP-8"},{"id":"CP-8(5)","oscal_id":"cp-8.5","family":"CP","title":"Alternate Telecommunication Service Testing","statement":"Test alternate telecommunication services <frequency>.","supplemental_guidance":"Alternate telecommunications services testing is arranged through contractual agreements with service providers. The testing may occur in parallel with normal operations to ensure that there is no degradation in organizational missions or functions.","implementation_level":"organization","parameters":[{"id":"cp-08.05_odp","label":"frequency"}],"methods":[{"method":"examine","label":"CP-08(05)-Examine"},{"method":"interview","label":"CP-08(05)-Interview"},{"method":"test","label":"CP-08(05)-Test"}],"related_controls":["CP-3"],"is_enhancement":true,"parent_id":"CP-8"}]},{"id":"CP-9","oscal_id":"cp-9","family":"CP","title":"System Backup","statement":"a. Conduct backups of user-level information contained in <system components> <frequency>;\nb. Conduct backups of system-level information contained in the system <frequency>;\nc. Conduct backups of system documentation, including security- and privacy-related documentation <frequency> ; and\nd. Protect the confidentiality, integrity, and availability of backup information.","supplemental_guidance":"System-level information includes system state information, operating system software, middleware, application software, and licenses. User-level information includes information other than system-level information. Mechanisms employed to protect the integrity of system backups include digital signatures and cryptographic hashes. Protection of system backup information while in transit is addressed by [MP-5](#mp-5) and [SC-8](#sc-8) . System backups reflect the requirements in contingency plans as well as other organizational requirements for backing up information. Organizations may be subject to laws, executive orders, directives, regulations, or policies with requirements regarding specific categories of information (e.g., personal health information). Organizational personnel consult with the senior agency official for privacy and legal counsel regarding such requirements.","implementation_level":"organization","parameters":[{"id":"cp-09_odp.01","label":"system components"},{"id":"cp-09_odp.02","label":"frequency"},{"id":"cp-09_odp.03","label":"frequency"},{"id":"cp-09_odp.04","label":"frequency"}],"objectives":[{"id":"cp-9_obj.a","label":"CP-09a.","text":"backups of user-level information contained in {{ insert: param, cp-09_odp.01 }} are conducted {{ insert: param, cp-09_odp.02 }};"},{"id":"cp-9_obj.b","label":"CP-09b.","text":"backups of system-level information contained in the system are conducted {{ insert: param, cp-09_odp.03 }};"},{"id":"cp-9_obj.c","label":"CP-09c.","text":"backups of system documentation, including security- and privacy-related documentation are conducted {{ insert: param, cp-09_odp.04 }};"},{"id":"cp-9_obj.d-1","label":"CP-09d.[01]","text":"the confidentiality of backup information is protected;"},{"id":"cp-9_obj.d-2","label":"CP-09d.[02]","text":"the integrity of backup information is protected;"},{"id":"cp-9_obj.d-3","label":"CP-09d.[03]","text":"the availability of backup information is protected."}],"methods":[{"method":"examine","label":"CP-09-Examine"},{"method":"interview","label":"CP-09-Interview"},{"method":"test","label":"CP-09-Test"}],"references":[{"title":"FIPS 140-3"},{"title":"FIPS 186-4"},{"title":"SP 800-34"},{"title":"SP 800-130"},{"title":"SP 800-152"}],"related_controls":["CP-2","CP-6","CP-10","MP-4","MP-5","SC-8","SC-12","SC-13","SI-4","SI-13"],"enhancements":[{"id":"CP-9(1)","oscal_id":"cp-9.1","family":"CP","title":"Testing for Reliability and Integrity","statement":"Test backup information <organization-defined frequency> to verify media reliability and information integrity.","supplemental_guidance":"Organizations need assurance that backup information can be reliably retrieved. Reliability pertains to the systems and system components where the backup information is stored, the operations used to retrieve the information, and the integrity of the information being retrieved. Independent and specialized tests can be used for each of the aspects of reliability. For example, decrypting and transporting (or transmitting) a random sample of backup files from the alternate storage or backup site and comparing the information to the same information at the primary processing site can provide such assurance.","implementation_level":"organization","parameters":[{"id":"cp-9.1_prm_1","label":"organization-defined frequency"},{"id":"cp-09.01_odp.01","label":"frequency"},{"id":"cp-09.01_odp.02","label":"frequency"}],"objectives":[{"id":"cp-9.1_obj-1","label":"CP-09(01)[01]","text":"backup information is tested {{ insert: param, cp-09.01_odp.01 }} to verify media reliability;"},{"id":"cp-9.1_obj-2","label":"CP-09(01)[02]","text":"backup information is tested {{ insert: param, cp-09.01_odp.02 }} to verify information integrity."}],"methods":[{"method":"examine","label":"CP-09(01)-Examine"},{"method":"interview","label":"CP-09(01)-Interview"},{"method":"test","label":"CP-09(01)-Test"}],"related_controls":["CP-4"],"is_enhancement":true,"parent_id":"CP-9"},{"id":"CP-9(2)","oscal_id":"cp-9.2","family":"CP","title":"Test Restoration Using Sampling","statement":"Use a sample of backup information in the restoration of selected system functions as part of contingency plan testing.","supplemental_guidance":"Organizations need assurance that system functions can be restored correctly and can support established organizational missions. To ensure that the selected system functions are thoroughly exercised during contingency plan testing, a sample of backup information is retrieved to determine whether the functions are operating as intended. Organizations can determine the sample size for the functions and backup information based on the level of assurance needed.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-09(02)-Examine"},{"method":"interview","label":"CP-09(02)-Interview"},{"method":"test","label":"CP-09(02)-Test"}],"related_controls":["CP-4"],"is_enhancement":true,"parent_id":"CP-9"},{"id":"CP-9(3)","oscal_id":"cp-9.3","family":"CP","title":"Separate Storage for Critical Information","statement":"Store backup copies of <critical system software and other security-related information> in a separate facility or in a fire rated container that is not collocated with the operational system.","supplemental_guidance":"Separate storage for critical information applies to all critical information regardless of the type of backup storage media. Critical system software includes operating systems, middleware, cryptographic key management systems, and intrusion detection systems. Security-related information includes inventories of system hardware, software, and firmware components. Alternate storage sites, including geographically distributed architectures, serve as separate storage facilities for organizations. Organizations may provide separate storage by implementing automated backup processes at alternative storage sites (e.g., data centers). The General Services Administration (GSA) establishes standards and specifications for security and fire rated containers.","implementation_level":"organization","parameters":[{"id":"cp-09.03_odp","label":"critical system software and other security-related information"}],"methods":[{"method":"examine","label":"CP-09(03)-Examine"},{"method":"interview","label":"CP-09(03)-Interview"}],"related_controls":["CM-2","CM-6","CM-8"],"is_enhancement":true,"parent_id":"CP-9"},{"id":"CP-9(4)","oscal_id":"cp-9.4","family":"CP","title":"Protection from Unauthorized Modification","statement":"","is_enhancement":true,"parent_id":"CP-9"},{"id":"CP-9(5)","oscal_id":"cp-9.5","family":"CP","title":"Transfer to Alternate Storage Site","statement":"Transfer system backup information to the alternate storage site <organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives>.","supplemental_guidance":"System backup information can be transferred to alternate storage sites either electronically or by the physical shipment of storage media.","implementation_level":"organization","parameters":[{"id":"cp-9.5_prm_1","label":"organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives"},{"id":"cp-09.05_odp.01","label":"time period"},{"id":"cp-09.05_odp.02","label":"transfer rate"}],"objectives":[{"id":"cp-9.5_obj-1","label":"CP-09(05)[01]","text":"system backup information is transferred to the alternate storage site for {{ insert: param, cp-09.05_odp.01 }};"},{"id":"cp-9.5_obj-2","label":"CP-09(05)[02]","text":"system backup information is transferred to the alternate storage site {{ insert: param, cp-09.05_odp.02 }}."}],"methods":[{"method":"examine","label":"CP-09(05)-Examine"},{"method":"interview","label":"CP-09(05)-Interview"},{"method":"test","label":"CP-09(05)-Test"}],"related_controls":["CP-7","MP-3","MP-4","MP-5"],"is_enhancement":true,"parent_id":"CP-9"},{"id":"CP-9(6)","oscal_id":"cp-9.6","family":"CP","title":"Redundant Secondary System","statement":"Conduct system backup by maintaining a redundant secondary system that is not collocated with the primary system and that can be activated without loss of information or disruption to operations.","supplemental_guidance":"The effect of system backup can be achieved by maintaining a redundant secondary system that mirrors the primary system, including the replication of information. If this type of redundancy is in place and there is sufficient geographic separation between the two systems, the secondary system can also serve as the alternate processing site.","implementation_level":"organization","objectives":[{"id":"cp-9.6_obj-1","label":"CP-09(06)[01]","text":"system backup is conducted by maintaining a redundant secondary system that is not collocated with the primary system;"},{"id":"cp-9.6_obj-2","label":"CP-09(06)[02]","text":"system backup is conducted by maintaining a redundant secondary system that can be activated without loss of information or disruption to operations."}],"methods":[{"method":"examine","label":"CP-09(06)-Examine"},{"method":"interview","label":"CP-09(06)-Interview"},{"method":"test","label":"CP-09(06)-Test"}],"related_controls":["CP-7"],"is_enhancement":true,"parent_id":"CP-9"},{"id":"CP-9(7)","oscal_id":"cp-9.7","family":"CP","title":"Dual Authorization for Deletion or Destruction","statement":"Enforce dual authorization for the deletion or destruction of <backup information>.","supplemental_guidance":"Dual authorization ensures that deletion or destruction of backup information cannot occur unless two qualified individuals carry out the task. Individuals deleting or destroying backup information possess the skills or expertise to determine if the proposed deletion or destruction of information reflects organizational policies and procedures. Dual authorization may also be known as two-person control. To reduce the risk of collusion, organizations consider rotating dual authorization duties to other individuals.","implementation_level":"organization","parameters":[{"id":"cp-09.07_odp","label":"backup information"}],"methods":[{"method":"examine","label":"CP-09(07)-Examine"},{"method":"interview","label":"CP-09(07)-Interview"},{"method":"test","label":"CP-09(07)-Test"}],"related_controls":["AC-3","AC-5","MP-2"],"is_enhancement":true,"parent_id":"CP-9"},{"id":"CP-9(8)","oscal_id":"cp-9.8","family":"CP","title":"Cryptographic Protection","statement":"Implement cryptographic mechanisms to prevent unauthorized disclosure and modification of <backup information>.","supplemental_guidance":"The selection of cryptographic mechanisms is based on the need to protect the confidentiality and integrity of backup information. The strength of mechanisms selected is commensurate with the security category or classification of the information. Cryptographic protection applies to system backup information in storage at both primary and alternate locations. Organizations that implement cryptographic mechanisms to protect information at rest also consider cryptographic key management solutions.","implementation_level":"organization","parameters":[{"id":"cp-09.08_odp","label":"backup information"}],"methods":[{"method":"examine","label":"CP-09(08)-Examine"},{"method":"interview","label":"CP-09(08)-Interview"},{"method":"test","label":"CP-09(08)-Test"}],"related_controls":["SC-12","SC-13","SC-28"],"is_enhancement":true,"parent_id":"CP-9"}]},{"id":"CP-10","oscal_id":"cp-10","family":"CP","title":"System Recovery and Reconstitution","statement":"Provide for the recovery and reconstitution of the system to a known state within <organization-defined time period consistent with recovery time and recovery point objectives> after a disruption, compromise, or failure.","supplemental_guidance":"Recovery is executing contingency plan activities to restore organizational mission and business functions. Reconstitution takes place following recovery and includes activities for returning systems to fully operational states. Recovery and reconstitution operations reflect mission and business priorities; recovery point, recovery time, and reconstitution objectives; and organizational metrics consistent with contingency plan requirements. Reconstitution includes the deactivation of interim system capabilities that may have been needed during recovery operations. Reconstitution also includes assessments of fully restored system capabilities, reestablishment of continuous monitoring activities, system reauthorization (if required), and activities to prepare the system and organization for future disruptions, breaches, compromises, or failures. Recovery and reconstitution capabilities can include automated mechanisms and manual procedures. Organizations establish recovery time and recovery point objectives as part of contingency planning.","implementation_level":"organization","parameters":[{"id":"cp-10_prm_1","label":"organization-defined time period consistent with recovery time and recovery point objectives"},{"id":"cp-10_odp.01","label":"time period"},{"id":"cp-10_odp.02","label":"time period"}],"objectives":[{"id":"cp-10_obj-1","label":"CP-10[01]","text":"the recovery of the system to a known state is provided within {{ insert: param, cp-10_odp.01 }} after a disruption, compromise, or failure;"},{"id":"cp-10_obj-2","label":"CP-10[02]","text":"a reconstitution of the system to a known state is provided within {{ insert: param, cp-10_odp.02 }} after a disruption, compromise, or failure."}],"methods":[{"method":"examine","label":"CP-10-Examine"},{"method":"interview","label":"CP-10-Interview"},{"method":"test","label":"CP-10-Test"}],"references":[{"title":"SP 800-34"}],"related_controls":["CP-2","CP-4","CP-6","CP-7","CP-9","IR-4","SA-8","SC-24","SI-13"],"enhancements":[{"id":"CP-10(1)","oscal_id":"cp-10.1","family":"CP","title":"Contingency Plan Testing","statement":"","is_enhancement":true,"parent_id":"CP-10"},{"id":"CP-10(2)","oscal_id":"cp-10.2","family":"CP","title":"Transaction Recovery","statement":"Implement transaction recovery for systems that are transaction-based.","supplemental_guidance":"Transaction-based systems include database management systems and transaction processing systems. Mechanisms supporting transaction recovery include transaction rollback and transaction journaling.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-10(02)-Examine"},{"method":"interview","label":"CP-10(02)-Interview"},{"method":"test","label":"CP-10(02)-Test"}],"is_enhancement":true,"parent_id":"CP-10"},{"id":"CP-10(3)","oscal_id":"cp-10.3","family":"CP","title":"Compensating Security Controls","statement":"Addressed through tailoring.","is_enhancement":true,"parent_id":"CP-10"},{"id":"CP-10(4)","oscal_id":"cp-10.4","family":"CP","title":"Restore Within Time Period","statement":"Provide the capability to restore system components within <restoration time periods> from configuration-controlled and integrity-protected information representing a known, operational state for the components.","supplemental_guidance":"Restoration of system components includes reimaging, which restores the components to known, operational states.","implementation_level":"organization","parameters":[{"id":"cp-10.04_odp","label":"restoration time periods"}],"methods":[{"method":"examine","label":"CP-10(04)-Examine"},{"method":"interview","label":"CP-10(04)-Interview"},{"method":"test","label":"CP-10(04)-Test"}],"related_controls":["CM-2","CM-6"],"is_enhancement":true,"parent_id":"CP-10"},{"id":"CP-10(5)","oscal_id":"cp-10.5","family":"CP","title":"Failover Capability","statement":"","is_enhancement":true,"parent_id":"CP-10"},{"id":"CP-10(6)","oscal_id":"cp-10.6","family":"CP","title":"Component Protection","statement":"Protect system components used for recovery and reconstitution.","supplemental_guidance":"Protection of system recovery and reconstitution components (i.e., hardware, firmware, and software) includes physical and technical controls. Backup and restoration components used for recovery and reconstitution include router tables, compilers, and other system software.","implementation_level":"organization","methods":[{"method":"examine","label":"CP-10(06)-Examine"},{"method":"interview","label":"CP-10(06)-Interview"},{"method":"test","label":"CP-10(06)-Test"}],"related_controls":["AC-3","AC-6","MP-2","MP-4","PE-3","PE-6"],"is_enhancement":true,"parent_id":"CP-10"}]},{"id":"CP-11","oscal_id":"cp-11","family":"CP","title":"Alternate Communications Protocols","statement":"Provide the capability to employ <alternative communications protocols> in support of maintaining continuity of operations.","supplemental_guidance":"Contingency plans and the contingency training or testing associated with those plans incorporate an alternate communications protocol capability as part of establishing resilience in organizational systems. Switching communications protocols may affect software applications and operational aspects of systems. Organizations assess the potential side effects of introducing alternate communications protocols prior to implementation.","implementation_level":"organization","parameters":[{"id":"cp-11_odp","label":"alternative communications protocols"}],"methods":[{"method":"examine","label":"CP-11-Examine"},{"method":"interview","label":"CP-11-Interview"},{"method":"test","label":"CP-11-Test"}],"related_controls":["CP-2","CP-8","CP-13"]},{"id":"CP-12","oscal_id":"cp-12","family":"CP","title":"Safe Mode","statement":"When <conditions> are detected, enter a safe mode of operation with <restrictions>.","supplemental_guidance":"For systems that support critical mission and business functions—including military operations, civilian space operations, nuclear power plant operations, and air traffic control operations (especially real-time operational environments)—organizations can identify certain conditions under which those systems revert to a predefined safe mode of operation. The safe mode of operation, which can be activated either automatically or manually, restricts the operations that systems can execute when those conditions are encountered. Restriction includes allowing only selected functions to execute that can be carried out under limited power or with reduced communications bandwidth.","implementation_level":"system","parameters":[{"id":"cp-12_odp.01","label":"restrictions"},{"id":"cp-12_odp.02","label":"conditions"}],"methods":[{"method":"examine","label":"CP-12-Examine"},{"method":"interview","label":"CP-12-Interview"},{"method":"test","label":"CP-12-Test"}],"related_controls":["CM-2","SA-8","SC-24","SI-13","SI-17"]},{"id":"CP-13","oscal_id":"cp-13","family":"CP","title":"Alternative Security Mechanisms","statement":"Employ <alternative or supplemental security mechanisms> for satisfying <security functions> when the primary means of implementing the security function is unavailable or compromised.","supplemental_guidance":"Use of alternative security mechanisms supports system resiliency, contingency planning, and continuity of operations. To ensure mission and business continuity, organizations can implement alternative or supplemental security mechanisms. The mechanisms may be less effective than the primary mechanisms. However, having the capability to readily employ alternative or supplemental mechanisms enhances mission and business continuity that might otherwise be adversely impacted if operations had to be curtailed until the primary means of implementing the functions was restored. Given the cost and level of effort required to provide such alternative capabilities, the alternative or supplemental mechanisms are only applied to critical security capabilities provided by systems, system components, or system services. For example, an organization may issue one-time pads to senior executives, officials, and system administrators if multi-factor tokens—the standard means for achieving secure authentication— are compromised.","implementation_level":"organization","parameters":[{"id":"cp-13_odp.01","label":"alternative or supplemental security mechanisms"},{"id":"cp-13_odp.02","label":"security functions"}],"methods":[{"method":"examine","label":"CP-13-Examine"},{"method":"interview","label":"CP-13-Interview"},{"method":"test","label":"CP-13-Test"}],"related_controls":["CP-2","CP-11","SI-13"]}]};
